mapper.select:
SELECT
sm.id,
sm.area_name,
sm.device_code as deviceCode,
sm.station_id as stationId,
cs.station_name as stationName,  
sm.lot_id as lotId,
cl.lot_code as lotCode,          
sm.device_type as deviceType,

sm.voltage,
sm.current,
sm.power,
sm.alarm_level as alarmLevel,

sm.monitor_status as monitorStatus,

sm.dispose_user as disposeUser,

sm.dispose_measure as disposeMeasure,
sm.dispose_time as disposeTime,
sm.monitor_time as monitorTime,
sm.remark,
sm.creator,

sm.create_time as createTime,
sm.update_time as updateTime
FROM status_monitor sm
LEFT JOIN charging_station cs ON sm.station_id = cs.id  
LEFT JOIN charging_lot cl ON sm.lot_id = cl.id          
WHERE
sm.deleted = 0



    AND sm.device_code LIKE CONCAT('%', #{deviceCode}, '%')




    AND sm.station_id = #{stationId}




    AND cs.station_name = #{stationName}




    AND sm.lot_id = #{lotId}




    AND cl.lot_code = #{lotCode}




    AND sm.device_type = #{deviceType}




    AND sm.voltage = #{voltage}




    AND sm.current = #{current}




    AND sm.power = #{power}




    AND sm.alarm_level = #{alarmLevel}




    AND sm.monitor_status = #{monitorStatus}




    AND sm.dispose_user = #{disposeUser}




    AND sm.dispose_measure LIKE CONCAT('%', #{disposeMeasure}, '%')




    AND sm.dispose_time BETWEEN #{disposeTime[0]} AND #{disposeTime[1]}




    AND sm.monitor_time BETWEEN #{monitorTime[0]} AND #{monitorTime[1]}




    AND sm.remark LIKE CONCAT('%', #{remark}, '%')




    AND sm.reserve1 = #{reserve1}




    AND sm.reserve2 = #{reserve2}




    AND sm.create_time BETWEEN #{createTime[0]} AND #{createTime[1]}


ORDER BY sm.id DESC
LIMIT #{pageSize} OFFSET ${(pageNo - 1) * pageSize}

SELECT COUNT(*)
FROM status_monitor sm
LEFT JOIN charging_station cs ON sm.station_id = cs.id  
LEFT JOIN charging_lot cl ON sm.lot_id = cl.id          
WHERE
sm.deleted = 0



    AND sm.device_code LIKE CONCAT('%', #{deviceCode}, '%')




    AND sm.station_id = #{stationId}




    AND cs.station_name = #{stationName}




    AND sm.lot_id = #{lotId}




    AND cl.lot_code = #{lotCode}




    AND sm.device_type = #{deviceType}




    AND sm.voltage = #{voltage}




    AND sm.current = #{current}




    AND sm.power = #{power}




    AND sm.alarm_level = #{alarmLevel}




    AND sm.monitor_status = #{monitorStatus}




    AND sm.dispose_user = #{disposeUser}




    AND sm.dispose_measure LIKE CONCAT('%', #{disposeMeasure}, '%')




    AND sm.dispose_time BETWEEN #{disposeTime[0]} AND #{disposeTime[1]}




    AND sm.monitor_time BETWEEN #{monitorTime[0]} AND #{monitorTime[1]}




    AND sm.remark LIKE CONCAT('%', #{remark}, '%')




    AND sm.reserve1 = #{reserve1}




    AND sm.reserve2 = #{reserve2}




    AND sm.create_time BETWEEN #{createTime[0]} AND #{createTime[1]}

SELECT COUNT(*) AS totalCount, SUM(CASE WHEN main.monitor_status = '正常' THEN 1 ELSE 0 END) AS normalCount, SUM(CASE WHEN main.monitor_status = '异常' THEN 1 ELSE 0 END) AS abnormalCount, SUM(CASE WHEN main.monitor_status = '处置中' THEN 1 ELSE 0 END) AS handlingCount, SUM(CASE WHEN main.monitor_status = '已恢复' THEN 1 ELSE 0 END) AS recoveredCount FROM status_monitor main WHERE main.deleted = 0
AND main.station_id = #{stationId}
AND main.device_type = #{deviceType}
AND main.monitor_time BETWEEN #{startTime} AND #{endTime}

SELECT DATE_FORMAT(t.monitor_time, '%H:%i') AS time, coalesce(ROUND(AVG(t.current), 2),0) AS `current`, coalesce(ROUND(AVG(t.power), 2),0) AS power, coalesce(ROUND(AVG(t.voltage), 2),0) AS voltage FROM status_monitor t WHERE t.deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
AND device_code = #{deviceCode}
GROUP BY DATE_FORMAT(t.monitor_time, '%H:%i') ORDER BY DATE_FORMAT(t.monitor_time, '%H:%i') ASC

SELECT sm.id, sm.device_code AS deviceName, cs.lon, cs.lat, sm.alarm_level AS alarmLevel FROM status_monitor sm LEFT JOIN charging_station cs ON sm.station_id = cs.id WHERE sm.deleted = 0 AND sm.monitor_status IN ('异常', '处置中')
AND sm.area_name = #{areaName}
ORDER BY sm.alarm_level DESC, sm.monitor_time DESC
